import React, { useState } from 'react';

const Gallery = ({ images }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isModalOpen, setIsModalOpen] = useState(false);

  const openModal = (index) => {
    setCurrentIndex(index);
    setIsModalOpen(true);
  };

  const closeModal = () => {
    setIsModalOpen(false);
  };

  const goToPrevious = () => {
    setCurrentIndex((prevIndex) => 
      prevIndex === 0 ? images.length - 1 : prevIndex - 1
    );
  };

  const goToNext = () => {
    setCurrentIndex((prevIndex) => 
      prevIndex === images.length - 1 ? 0 : prevIndex + 1
    );
  };

  return (
    <div className="gallery">
      {/* Main Image */}
      <div className="main-image" onClick={() => openModal(0)}>
        <img 
          src={images[0]} 
          alt="Main property view" 
          className="gallery-main-img"
        />
        <div className="image-overlay">
          <span>Click to view gallery ({images.length} photos)</span>
        </div>
      </div>

      {/* Thumbnails */}
      <div className="thumbnails">
        {images.slice(1, 7).map((image, index) => (
          <div 
            key={index}
            className="thumbnail"
            onClick={() => openModal(index + 1)}
          >
            <img 
              src={image} 
              alt={`Property view ${index + 2}`}
              className="thumbnail-img"
            />
          </div>
        ))}
        {images.length > 7 && (
          <div 
            className="thumbnail more"
            onClick={() => openModal(6)}
          >
            <span>+{images.length - 7} more</span>
          </div>
        )}
      </div>

      {/* Modal Lightbox */}
      {isModalOpen && (
        <div className="modal-overlay" onClick={closeModal}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <button className="close-btn" onClick={closeModal}>
                ×
              </button>
              <div className="image-counter">
                {currentIndex + 1} / {images.length}
              </div>
            </div>
            
            <div className="modal-image">
              <button 
                className="nav-btn prev" 
                onClick={goToPrevious}
              >
                ‹
              </button>
              
              <img 
                src={images[currentIndex]} 
                alt={`Property view ${currentIndex + 1}`}
                className="modal-main-img"
              />
              
              <button 
                className="nav-btn next" 
                onClick={goToNext}
              >
                ›
              </button>
            </div>

            <div className="modal-thumbnails">
              {images.map((image, index) => (
                <div 
                  key={index}
                  className={`modal-thumbnail ${index === currentIndex ? 'active' : ''}`}
                  onClick={() => setCurrentIndex(index)}
                >
                  <img 
                    src={image} 
                    alt={`Thumbnail ${index + 1}`}
                  />
                </div>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Gallery;
